// Original CC0 fixture generator. Run from repository root; see README.md.
import {execFileSync}from'node:child_process';import{readFileSync,writeFileSync}from'node:fs';import omggif from'omggif';import{readPng}from'../../../app/formats.mjs';const bin=process.env.ASEPRITE_BIN,root='tests/fixtures/tag-traversal';let results=[];
for(const shape of ['full-reverse','nested-contained','one-pingpong']){let code=`local s=Sprite(1,1);for i=1,5 do if i>1 then s:newEmptyFrame() end;local im=Image(1,1);im:drawPixel(0,0,app.pixelColor.rgba(i*40,0,0,255));s:newCel(s.layers[1],i,im);s.frames[i].duration=.1 end\n`;code+=shape==='full-reverse'?`local t=s:newTag(1,5);t.name='clip';t.aniDir=AniDir.REVERSE;t.repeats=2;`:shape==='nested-contained'?`local t=s:newTag(2,5);t.name='clip';t.aniDir=AniDir.PING_PONG;t.repeats=3;local b=s:newTag(3,4);b.name='inner';b.aniDir=AniDir.REVERSE;b.repeats=2;`:`local t=s:newTag(3,3);t.name='clip';t.aniDir=AniDir.PING_PONG;t.repeats=3;`;code+=`s:saveAs(app.params.path);s:close()`;writeFileSync(`${root}/${shape}.lua`,code);execFileSync(bin,['--batch','--script-param',`path=${root}/${shape}.aseprite`,'--script',`${root}/${shape}.lua`]);for(const tag of [null,'clip',...(shape==='nested-contained'?['inner']:[])])for(const sub of [false,true])for(const format of ['gif','sheet']){const path=`${root}/exports/${shape}-${tag}-${sub}-${format}.`+(format==='gif'?'gif':'png');const opt=[...(sub?['--play-subtags']:[]),...(tag?['--tag',tag]:[])];const args=['--batch',...opt,`${root}/${shape}.aseprite`,...(format==='gif'?['--save-as',path]:['--sheet-type','horizontal','--sheet',path])];execFileSync(bin,args);let frames=[];if(format==='gif'){const g=new omggif.GifReader(readFileSync(path));let p=new Uint8Array(4);for(let i=0;i<g.numFrames();i++){g.decodeAndBlitFrameRGBA(i,p);frames.push({frame:p[0]/40-1,ms:g.frameInfo(i).delay*10})}}else{const p=readPng(readFileSync(path));frames=Array.from({length:p.width},(_,i)=>({frame:p.rgba[i*4]/40-1}))}results.push({fixture:shape,tag,subtags:sub,format,args,frames});}}
writeFileSync(`${root}/cli-scope-vectors.json`,JSON.stringify(results,null,2)+'\n');console.log(results.map(x=>`${x.fixture} ${x.tag} sub${x.subtags} ${x.format}: ${x.frames.map(f=>f.frame+'('+f.ms+')').join(',')}`).join('\n'));
